import React from 'react';
import { motion } from 'framer-motion';

function PageHeader({ title, subtitle }) {
  return (
    <div className="relative pt-32 pb-16 bg-slate-900 overflow-hidden">
      <div className="absolute inset-0 opacity-20">
        <div className="absolute inset-0 bg-gradient-to-br from-emerald-600 to-transparent" />
      </div>
      <div className="relative max-w-7xl mx-auto px-6 text-center">
        <motion.h1 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-4xl md:text-5xl font-bold text-white mb-4 font-poppins"
        >
          {title}
        </motion.h1>
        <motion.p 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="text-emerald-400 font-medium text-lg"
        >
          {subtitle}
        </motion.p>
      </div>
    </div>
  );
}

export default PageHeader;
